    });

    it('handles output field as array of content blocks', () => {
      const translator = createTranslator();

      translator.translate({
        sessionUpdate: 'tool_call',
        toolCallId: 'toolu_arr2',
        rawInput: {},
        _meta: { claudeCode: { toolName: 'Read' } },
