  sessionStart: number;
  activeMessage: {
    type: "agent_message" | "agent_thought";
    content: string;
  } | null;
  pendingTools: Map<
    string,
    { tool: string; input: unknown; startTime: number }
  >;
}

export function createTranslator(): RalphTranslator {
  const state: TranslatorState = {
    sessionStart: Date.now(),
    activeMessage: null,
    pendingTools: new Map(),
