  /No onPreToolUseHook found(?:\s+for\s+tool\s+use(?:\s+ID:\s*toolu_[A-Za-z0-9]{24})?)?/gi,
];

/**
 * Prefixes that could indicate the start of a noise pattern.
 * Used for boundary-aware buffering to handle noise split across chunks.
 * These are substrings that, if a chunk ends with them, indicate we should
 * buffer until we can determine if it's noise or not.
 *
 * The full pattern is: "No on[Pre|Post]ToolUseHook found for tool use ID: toolu_XXXX"
 * We need to catch partial matches at chunk boundaries.
 */
const NOISE_PREFIXES = [
  "No on", // Start of any hook warning
  "No onPre", // Partial Pre
  "No onPreToolUseHook", // Pre without "found"
  "No onPreToolUseHook found", // Pre complete but may have more
  "No onPost", // Partial Post
  "No onPostToolUseHook", // Post without "found"
  "No onPostToolUseHook found", // Post complete but may have more
  // Patterns with "for tool use" variants
  "No onPreToolUseHook found for",
  "No onPreToolUseHook found for tool",
  "No onPreToolUseHook found for tool use",
  "No onPreToolUseHook found for tool use ID",
  "No onPreToolUseHook found for tool use ID:",
  "No onPreToolUseHook found for tool use ID: toolu_",
  "No onPostToolUseHook found for",
  "No onPostToolUseHook found for tool",
  "No onPostToolUseHook found for tool use",
  "No onPostToolUseHook found for tool use ID",
  "No onPostToolUseHook found for tool use ID:",
  "No onPostToolUseHook found for tool use ID: toolu_",
];

// Maximum length of a noise prefix - used for efficient suffix checking
const MAX_NOISE_PREFIX_LEN = Math.max(...NOISE_PREFIXES.map((p) => p.length));

/**
 * Check if the content ends with a potential partial noise pattern.
 * Returns the partial match length if found, 0 otherwise.
 */
function getPartialNoiseLength(content: string): number {
  // Check suffixes of increasing length up to the max prefix length
  const checkLen = Math.min(content.length, MAX_NOISE_PREFIX_LEN + 30); // +30 for partial tool ID
  const suffix = content.slice(-checkLen);

  // Check each possible suffix length
  for (let len = Math.min(suffix.length, MAX_NOISE_PREFIX_LEN + 30); len > 0; len--) {
