    // Check if this suffix matches any prefix
    for (const prefix of NOISE_PREFIXES) {
      if (candidate === prefix) {
        return len;
      }
      // Also check for partial tool ID (toolu_ followed by up to 24 chars)
      if (prefix.endsWith("toolu_") && candidate.startsWith(prefix)) {
        const afterToolu = candidate.slice(prefix.length);
        if (afterToolu.length < 24 && /^[A-Za-z0-9]*$/.test(afterToolu)) {
