  "No on", // Start of any hook warning
  "No onPre", // Partial Pre
  "No onPreToolUseHook", // Pre without "found"
  "No onPreToolUseHook found", // Pre complete but may have more
  "No onPost", // Partial Post
  "No onPostToolUseHook", // Post without "found"
  "No onPostToolUseHook found", // Post complete but may have more
  // Patterns with "for tool use" variants
  "No onPreToolUseHook found for",
  "No onPreToolUseHook found for tool",
  "No onPreToolUseHook found for tool use",
  "No onPreToolUseHook found for tool use ID",
  "No onPreToolUseHook found for tool use ID:",
  "No onPreToolUseHook found for tool use ID: toolu_",
  "No onPostToolUseHook found for",
  "No onPostToolUseHook found for tool",
  "No onPostToolUseHook found for tool use",
  "No onPostToolUseHook found for tool use ID",
  "No onPostToolUseHook found for tool use ID:",
  "No onPostToolUseHook found for tool use ID: toolu_",
];

