function processChunkWithBuffer(text: string): string | null {
  // Combine buffer with new text
  const combined = state.noiseBuffer + text;
  state.noiseBuffer = "";

  // Strip complete noise patterns
  const cleaned = stripNoise(combined);
  if (cleaned === null) {
    return null;
  }

  // Check if the cleaned content ends with a partial noise pattern
  const partialLen = getPartialNoiseLength(cleaned);
  if (partialLen > 0) {
    // Buffer the potential partial match
    state.noiseBuffer = cleaned.slice(-partialLen);
    const safeContent = cleaned.slice(0, -partialLen);

    // If nothing safe to emit, return null
    if (safeContent.length === 0) {
      return null;
    }
    return safeContent;
  }

  return cleaned;
}

